class Solution { fun largest1BorderedSquare(grid:Array<IntArray>):Int{val rows=grid.size;val columns=grid[0].size;val left=Array(rows){IntArray(columns)};val up=Array(rows){IntArray(columns)};var best=0;for(r in 0 until rows)for(c in 0 until columns)if(grid[r][c]==1){left[r][c]=1+if(c>0)left[r][c-1] else 0;up[r][c]=1+if(r>0)up[r-1][c] else 0;for(side in minOf(left[r][c],up[r][c]) downTo best+1)if(left[r-side+1][c]>=side&&up[r][c-side+1]>=side){best=side;break}};return best*best} }
